    domain: "sculpture",
    artifactType: "Sculpture monumentale / Ronde-bosse en marbre",
    title: "Monument des Néréides de Xanthe : Statues d'auras marines au drapé mouillé du dynaste Erbinna",
    site: "British Museum (Londres)",
    originSite: "Xanthe (Lycie, Asie Mineure)",
    locationType: "museum",
